import fs from 'node:fs/promises';
const h={apikey:process.env.SUPABASE_KEY,Authorization:'Bearer '+process.env.SUPABASE_KEY,'Content-Type':'application/json',Prefer:'return=representation'};
async function db(t,q={},method='GET',body){const r=await fetch(process.env.SUPABASE_URL+'/rest/v1/'+t+'?'+new URLSearchParams(q),{method,headers:h,body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(t+' '+r.status);return r.json();}
const [mitchell]=await db('market_touches',{contact_id:'eq.d2ec0661-3965-4fc3-a38c-80cc0afb0bf4',direction:'eq.inbound',order:'created_at.desc',limit:1});
const [task]=await db('crm_tasks',{id:'eq.6dfb9c95-1a37-453c-a5d1-85a5ff9e2f4c'});
if(!task.description.includes('owner-outcome-20260916'))await db('crm_tasks',{id:'eq.'+task.id},'PATCH',{priority:'urgent',description:JSON.stringify({review_key:'owner-outcome-20260916',next_action:'Mitchell checked at 11:09 whether John was still visiting and said he would leave around11:30. Ask owner whether visit or offline conversation occurred before replying. No fabricated explanation or new appointment.',source_touch:mitchell.id,latest_message:mitchell.notes,previous_description:task.description})});
const biaTasks=await db('crm_tasks',{related_id:'eq.799ddedd-d089-4158-a793-8d64dd4c9a14',status:'in.(open,in_progress)',select:'id,source_key'});
for(const t of biaTasks.filter(t=>t.source_key?.startsWith('windsor-published-v1:')))await db('crm_tasks',{id:'eq.'+t.id},'PATCH',{status:'completed',completed_at:new Date().toISOString(),completed_by_name:'John — reply review',outcome_note:'Jodie reports no supplier process or current moving inquiries. Courteous acknowledgment sent; no automatic follow-up.'});
const [amandaTouch]=await db('market_touches',{id:'eq.c882f45b-9f62-4c66-8ac6-04a2681b5527'});
await db('market_touches',{id:'eq.'+amandaTouch.id},'PATCH',{outcome_code:'partner_marketing_commitment',next_step:'Amanda plans to include AMANDA15 card in buyer packages. Card delivered and acknowledgment sent. Await actual referrals; this is intent, not booked revenue.',metadata:{...amandaTouch.metadata,classification_reviewed_at:new Date().toISOString(),previous_outcome:amandaTouch.metadata?.previous_outcome||amandaTouch.outcome_code}});
const followup=JSON.parse(await fs.readFile('partnership-system/state/kingsville-bia-close-20260916.json'));
const events=await db('email_provider_events',{provider_message_id:'eq.'+followup.result.messageId,select:'event_type,occurred_at'});
await fs.writeFile('partnership-system/state/operations-review-20260916.json',JSON.stringify({at:new Date().toISOString(),mitchellTouch:mitchell.id,biaTasksClosed:biaTasks.length,biaEvents:events},null,2));console.log(JSON.stringify({mitchell:'owner_outcome_pending',biaEvents:events}));
